:root {
    
    --space-2: 0.125rem;
    --space-4: 0.25rem;
    --space-6: 0.375rem;
    --space-8: 0.5rem;
    --space-10: 0.625rem;
    --space-12: 0.75rem;
    --space-14: 0.875rem;
    --space-16: 1rem;
    --space-24: 1.5rem;
    --space-32: 2rem;
    --space-40: 2.5rem;
    --settings-heading-inset: 5px;
    
    --panel-edge-gap: 6px;
    --panel-card-bg: var(--bg-card, var(--bg));
    --panel-card-radius: var(--radius-lg);
    --panel-card-border: 1px solid rgba(0, 0, 0, 0.08);
    --panel-card-shadow: none;

    
    --chat-column-width: 720px;
    
    --chat-copy-column: var(--chat-column-width);
    --chat-input-column-extra: 1.25rem;
    --chat-input-column-width: calc(var(--chat-column-width) + var(--chat-input-column-extra));
    --welcome-chat-input-column-width: 40rem;
    --chat-message-font-size: 15px;

    
    --radius-xs: 3px;
    --radius-sm: 5px;
    --radius-md: 8px;
    --radius-lg: 12px;
    --chat-task-block-width: 348px;   
    --chat-turn-fold-width: calc(var(--chat-task-block-width) * 1.25); 

    
    --radius-input: 6px;        
    --radius-chat-surface: 16px; 
    --radius-card: 8px;         
    --radius-chat-card: 8px; 
    --radius-chat-card-inner: max(2px, calc(var(--radius-chat-card) - 2px));
    --border-width: 1px;        
    --link: var(--accent, #537D96);
    --link-hover: var(--accent-hover, var(--link));
    --link-rgb: var(--accent-rgb, 83, 125, 150);
    --permission-auto: #5f93aa;
    --permission-auto-rgb: 95, 147, 170;
    --permission-auto-border: rgba(var(--permission-auto-rgb), 0.32);
    --permission-auto-bg: rgba(var(--permission-auto-rgb), 0.08);
    
    --success: #5a9;
    
    --plugin-native-surface-success: #2f7d55;
    --gold: #b48a44;
    --gold-rgb: 180, 138, 68;
    --danger-bg: #C0616B;
    --danger-bg-hover: #A8505A;
    
    --bg-card-alt: var(--overlay-light, rgba(0,0,0,0.03));
    --bg-input: var(--bg);
    --bg-main: #faf8f5;
    --bg-surface: #fffdf9;
    --bg-tertiary: #eee;
    --border-muted: #e8e4df;
    --color-err: #c44;
    --color-ok: #5a9a6a;
    --floating-input-close-dur: var(--duration-fast);
    --floating-input-closing-scale: 0.99;
    --floating-input-ease: cubic-bezier(0.22, 1, 0.36, 1);
    --floating-input-open-dur: var(--duration-slow);
    --floating-input-pre-scale: 0.97;
    --fs-small: 12px;
    --motion-fast: 140ms;
    --right-workspace-desk-height: 640px;
    --sage: #8aa083;
    --text-link: #6b8aad;
    --warning: #a26a15;
    
    --scrim-15: rgba(0, 0, 0, 0.15);
    --scrim-30: rgba(0, 0, 0, 0.3);
    --scrim-35: rgba(0, 0, 0, 0.35);
    --scrim-45: rgba(0, 0, 0, 0.45);
    
    --shadow-xs: 0 1px 3px var(--shadow);
    --shadow-xs-soft: 0 1px 3px rgba(0, 0, 0, 0.04);
    --shadow-xs-strong: 0 1px 3px rgba(0, 0, 0, 0.06);
    --shadow-sm: 0 1px 4px var(--shadow);
    --shadow-sm-soft: 0 1px 4px rgba(0, 0, 0, 0.06);
    --shadow-sm-strong: 0 1px 4px rgba(0, 0, 0, 0.07);
    --shadow-md: 0 2px 8px var(--shadow);
    --shadow-lg: 0 4px 12px var(--shadow);
    --shadow-xl: 0 4px 16px var(--shadow);
    --shadow-2xl: 0 12px 48px var(--shadow);
    --shadow-ring: 0 0 0 2px var(--accent-light);
    --shadow-xs-ring: 0 1px 3px var(--shadow), 0 0 0 2px rgba(var(--accent-rgb), 0.12);
    
    --on-accent: #fff;
    
    --step-parallel: #8da4b8;
    --step-pipeline: #c4a87d;
    --step-log: #8baa8b;
    --step-done: #5aa07a;
    --step-failed: #c46a6a;
    
    --tab-close-danger: #C0392B;             
    --tab-close-danger-rgb: 192, 57, 43;
    --automation-danger-rgb: 217, 83, 79;    
    --desk-ctx-danger-rgb: 200, 80, 80;      
    
    --window-close-danger: #b56b66;          
    --tooltip-bg: var(--text);
    --tooltip-text: var(--bg);
    --tooltip-border: transparent;
    --tooltip-shadow: rgba(0, 0, 0, 0.16);

    
    --scrim-15: rgba(0, 0, 0, 0.15);
    --scrim-30: rgba(0, 0, 0, 0.3);
    --scrim-35: rgba(0, 0, 0, 0.35);
    --scrim-45: rgba(0, 0, 0, 0.45);

    
    --duration-instant: 0.1s;       
    --duration-fast:    0.15s;      
    --duration-slow:    0.25s;      
    --duration-spinner: 0.8s;       

    
    --ease-out:      cubic-bezier(0.16, 1, 0.3, 1);
    --ease-in:       cubic-bezier(0.7, 0, 0.84, 0);
    --ease-standard: cubic-bezier(0.2, 0, 0, 1);
    --ease-smooth:   cubic-bezier(0.22, 0.68, 0, 1);

    
    --fs-title:   1rem;      
    --fs-body:    0.9rem;    
    --fs-ui:      0.82rem;   
    --fs-caption: 0.78rem;   
    --fs-hint:    0.7rem;    
    --fs-micro:   0.62rem;   

    
    --font-ui: -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, 'PingFang SC', 'Microsoft YaHei', sans-serif;
    --reading-font-family: 'PT Serif', 'Noto Serif SC', 'Source Han Serif SC', 'Songti SC', 'STSong', serif;
    --font-serif: var(--reading-font-family);
    --font-serif-text: var(--reading-font-family);
    --font-mono: 'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo, monospace;

    
    --editor-markdown-font-size: 16px;
    --editor-markdown-h1-font-size: 28px;
    --editor-markdown-h2-font-size: 21px;
    --editor-markdown-h3-font-size: 18px;
    --editor-markdown-h4-font-size: 16px;
    --editor-markdown-h5-font-size: 15px;
    --editor-markdown-h6-font-size: 14px;
    --editor-markdown-line-height: 1.5;
    --editor-markdown-content-padding-x: var(--space-24);
    --editor-markdown-content-width: 720px;

    
    --paper-texture-card-blend-mode: lighten;

    
    --sidebar-width: 240px;
    --jian-sidebar-width: 260px;
    --channel-inspector-width: 280px;
    --preview-panel-width: 580px;
    --jian-columns: 1;

    
    --titlebar-h: 44px;

}
:where([data-hana-app-ui]), :where([data-hana-app-ui]) *, :where([data-hana-app-ui])::before, :where([data-hana-app-ui])::after, :where([data-hana-app-ui]) *::before, :where([data-hana-app-ui]) *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
    scrollbar-width: thin;
    scrollbar-color: rgba(128, 128, 128, 0.2) transparent;
}
.hana-toggle {
    width: 36px;
    height: 20px;
    border-radius: calc(var(--toggle-radius, 5px) * var(--corner-radius-scale, 1)); corner-shape: squircle;
    border: none;
    background: var(--overlay-medium);
    cursor: default;
    position: relative;
    transition: background var(--duration-slow);
    flex-shrink: 0;
    padding: 0;
}
.hana-toggle::after {
    content: "";
    position: absolute;
    top: 3px;
    left: 3px;
    width: 14px;
    height: 14px;
    border-radius: calc(var(--toggle-thumb-radius, 3px) * var(--corner-radius-scale, 1)); corner-shape: squircle;
    background: #fff;
    transition: transform var(--duration-slow);
}
.hana-toggle:hover {
    filter: brightness(0.92);
}
.hana-toggle[data-checked] {
    background: var(--accent);
}
.hana-toggle[data-checked]::after {
    transform: translateX(16px);
}
.hana-toggle[data-disabled],
.hana-toggle:disabled {
    opacity: 0.35;
    cursor: not-allowed;
    pointer-events: none;
}
.hana-toggle[data-readonly] {
    pointer-events: none;
}
.hana-toggle[data-loading] {
    opacity: 0.55;
    animation: hana-toggle-loading-pulse 1.2s ease-in-out infinite;
}
.hana-toggle[data-loading]::after {
    transform: translateX(8px);
}
.hana-toggle-label {
    font-size: var(--fs-caption);
    color: var(--text-muted);
}
@keyframes hana-toggle-loading-pulse {
    0%, 100% { opacity: 0.55; }
    50% { opacity: 0.35; }
}
